#!/usr/bin/env node
// dtcg-to-css.mjs — emit shadcn-compatible CSS custom properties from the
// DTCG token file, so web code and Penpot designs share ONE token source.
//
// Reads  ../tokens/hologram-tokens.json  (generated by shadcn-to-dtcg.mjs)
// Writes ../css/hologram-theme.css       (:root = light, .dark = dark)
//
// --check: round-trip parity gate — every emitted color var must equal the
// direct oklch→hex conversion of the original shadcn registry value.
//
// Usage: node dtcg-to-css.mjs [--check]

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { oklchToHex, STATE_ROLES } from "./shadcn-to-dtcg.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const tokens = JSON.parse(readFileSync(join(here, "..", "tokens", "hologram-tokens.json"), "utf8"));
const outPath = join(here, "..", "css", "hologram-theme.css");

// Resolve {core.x.y} references against the core set.
function resolveRef(value) {
  const m = /^\{(.+)\}$/.exec(value);
  if (!m) return value;
  let node = tokens;
  for (const part of m[1].split(".")) node = node?.[part];
  if (node?.$value === undefined) throw new Error(`unresolvable ref: ${value}`);
  return resolveRef(node.$value);
}

function cssVarsOf(setName) {
  const out = {};
  for (const [name, node] of Object.entries(tokens[setName].color))
    out[name] = resolveRef(node.$value);
  return out;
}

// The single elevation of a set, as a CSS box-shadow value.
function shadowOf(setName) {
  const [s] = tokens[setName].shadow.overlay.$value;
  return `${s.offsetX}px ${s.offsetY}px ${s.blur}px ${s.spread}px ${s.color}`.replace(/\b0px/g, "0");
}

// Mode independent constants: hairline, keyboard focus, motion.
const constants = {
  "border-width": tokens.global.border.width.$value,
  "ring-width": tokens.global.focus["ring-width"].$value,
  "ring-offset": tokens.global.focus["ring-offset"].$value,
  duration: tokens.global.motion.duration.$value,
  ease: tokens.global.motion.ease.$value,
};

function block(selector, vars, extra = {}) {
  const lines = Object.entries({ ...vars, ...extra })
    .map(([k, v]) => `  --${k}: ${v};`)
    .join("\n");
  return `${selector} {\n${lines}\n}`;
}

const radiusLg = tokens.global.radius.lg.$value;
const radiusRem = `${parseFloat(radiusLg) / 16}rem`;

const css = `/* GENERATED by brand/scripts/dtcg-to-css.mjs — do not edit by hand.
 * Source of truth: brand/tokens/hologram-tokens.json
 * Derived from shadcn/ui (MIT, https://ui.shadcn.com) neutral base. */

${block(":root", cssVarsOf("light"), {
  radius: radiusRem,
  "font-sans": tokens.global.font.family.sans.$value,
  "font-mono": tokens.global.font.family.mono.$value,
  ...constants,
  "shadow-overlay": shadowOf("light"),
})}

${block(".dark", cssVarsOf("dark"), { "shadow-overlay": shadowOf("dark") })}
`;

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, css);
console.log(`wrote ${outPath}`);

// The Hologram brand layer: warm ground, one orange accent. Same variable
// names as the baseline, so it drops into any shadcn project unchanged.
const warmPath = join(here, "..", "css", "hologram-warm.css");
const warmCss = `/* GENERATED by brand/scripts/dtcg-to-css.mjs — do not edit by hand.
 * The Hologram brand layer: warm paper (:root) and warm dark (.dark),
 * accent #e93b01. Source of truth: brand/tokens/hologram-tokens.json */

${block(":root", cssVarsOf("hologram-light"), {
  radius: radiusRem,
  "font-sans": tokens.global.font.family.sans.$value,
  "font-display": tokens.global.font.family.display.$value,
  "font-mono": tokens.global.font.family.mono.$value,
  "tracking-display": tokens.global.font.tracking.display.$value,
  "tracking-caps": tokens.global.font.tracking.caps.$value,
  ...constants,
  "shadow-overlay": shadowOf("hologram-light"),
})}

${block(".dark", cssVarsOf("hologram-dark"), { "shadow-overlay": shadowOf("hologram-dark") })}
`;
writeFileSync(warmPath, warmCss);
console.log(`wrote ${warmPath}`);

if (process.argv.includes("--check")) {
  const source = JSON.parse(
    readFileSync(join(here, "..", "tokens", "source", "shadcn-neutral.json"), "utf8"));
  const failures = [];
  let total = 0;
  // Deliberate brand divergences from the shadcn registry, asserted
  // EXACTLY — a checked contract, never drift. Rationale lives beside
  // BRAND_EXTENSIONS in shadcn-to-dtcg.mjs.
  const DIVERGENT = { "light/sidebar-primary": "#1447e6" };
  for (const mode of ["light", "dark"]) {
    const emitted = cssVarsOf(mode);
    for (const [name, oklch] of Object.entries(source.cssVarsV4[mode])) {
      if (name === "radius") continue;
      total++;
      const expected = DIVERGENT[`${mode}/${name}`] ?? oklchToHex(oklch);
      if (emitted[name] !== expected)
        failures.push(`${mode}/${name}: emitted ${emitted[name]}, expected ${expected}`);
    }
  }
  // Presence gate: the brand-extension roles must exist in every set, so
  // a future variant or theme cannot ship without them.
  for (const setName of ["light", "dark", "hologram-light", "hologram-dark"])
    for (const role of ["success", "success-foreground", "muted-foreground-subtle", ...STATE_ROLES])
      if (!cssVarsOf(setName)[role]) {
        total++;
        failures.push(`${setName}/${role}: missing brand-extension token`);
      }
  if (failures.length) {
    console.error("ROUND-TRIP PARITY FAILED:\n" + failures.join("\n"));
    process.exit(1);
  }
  console.log(`check: ${total}/${total} color vars round-trip exactly (light+dark vs shadcn registry)`);
  verifyComponentContrast();
}

// Component contrast gate: every foreground/background pair a component
// paints in the Hologram sets, measured with the WCAG 2.x relative-luminance
// formula. Text needs 4.5:1 (SC 1.4.3); focus rings need 3:1 against the
// grounds they sit on (SC 1.4.11). Translucent colours are flattened over
// the set's background first.
function verifyComponentContrast() {
  const TEXT = 4.5, NON_TEXT = 3.0;
  const PAIRS = [
    // [foreground, [grounds], minimum]
    ["foreground", ["background", "card", "muted"], TEXT],
    ["card-foreground", ["card"], TEXT],
    ["popover-foreground", ["popover"], TEXT],
    ["muted-foreground", ["background", "card", "muted"], TEXT],
    ["primary-foreground", ["primary"], TEXT],
    ["secondary-foreground", ["secondary"], TEXT],
    ["accent-foreground", ["accent"], TEXT],
    ["destructive", ["background", "card", "destructive-subtle"], TEXT],
    ["destructive-foreground", ["destructive"], TEXT],
    ["brand-text", ["background", "card", "muted"], TEXT],
    ["sidebar-foreground", ["sidebar"], TEXT],
    ["sidebar-accent-foreground", ["sidebar-accent"], TEXT],
    ["ring", ["background", "card"], NON_TEXT],
    ["sidebar-ring", ["sidebar"], NON_TEXT],
    // The orange is a mark and a fill, never a ground for body text. The
    // brand colour is fixed, so white on it (4.13) is held to the large-text
    // and non-text floor, not AA body text. Text in the brand colour uses
    // brand-text, which the TEXT row above holds to 4.5.
    ["brand-foreground", ["brand"], NON_TEXT],
    ["sidebar-primary-foreground", ["sidebar-primary"], NON_TEXT],
  ];
  const lum = (hex) => {
    const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
      .map((v) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  const ratio = (a, b) => {
    const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
    return (hi + 0.05) / (lo + 0.05);
  };
  const flat = (top, under) => {
    if (top.length !== 9) return top;
    const a = parseInt(top.slice(7, 9), 16) / 255;
    const ch = (hex, i) => parseInt(hex.slice(i, i + 2), 16);
    return "#" + [1, 3, 5].map((i) =>
      Math.round(ch(top, i) * a + ch(under, i) * (1 - a)).toString(16).padStart(2, "0")).join("");
  };
  const failures = [];
  let total = 0;
  for (const setName of ["hologram-light", "hologram-dark"]) {
    const c = cssVarsOf(setName);
    const solid = (role) => flat(c[role], c.background);
    for (const [fg, grounds, min] of PAIRS)
      for (const ground of grounds) {
        total++;
        if (!c[fg] || !c[ground]) {
          failures.push(`${setName}/${fg} on ${ground}: missing token`);
          continue;
        }
        const r = ratio(solid(fg), solid(ground));
        if (r < min)
          failures.push(`${setName}/${fg} ${c[fg]} on ${ground} ${solid(ground)}: ${r.toFixed(2)} < ${min}`);
      }
  }
  if (failures.length) {
    console.error("COMPONENT CONTRAST FAILED:\n" + failures.join("\n"));
    process.exit(1);
  }
  console.log(`check: ${total}/${total} component contrast pairs pass (text 4.5, ring 3.0; hologram-light+hologram-dark)`);
}
